<script lang="ts">
 import { onMount } from 'svelte';
 import CardFace from './CardFace.svelte';
 import { cards, deckSize, pendingEffects, type Card } from '$lib/game/cards';
 let category = $state('All cards'); let query = $state(''); let backs = $state(false); let large = $state(false); let selected = $state<Card|null>(null); let favorites = $state<string[]>([]); let storageAvailable = $state(true);
 const categories = ['All cards','Tea','Flavor','Topping','Special','Action'];
 let visible = $derived(cards.filter(c => (category==='All cards'||c.category===category) && `${c.name} ${c.family} ${c.effect}`.toLowerCase().includes(query.toLowerCase())));
 onMount(()=>{try{const saved=JSON.parse(localStorage.getItem('sabobatage-art-favorites')||'[]');if(Array.isArray(saved)) favorites=saved.filter((v:unknown):v is string=>typeof v==='string');}catch{storageAvailable=false;}});
 function favorite(id:string){favorites=favorites.includes(id)?favorites.filter(v=>v!==id):[...favorites,id];try{localStorage.setItem('sabobatage-art-favorites',JSON.stringify(favorites));}catch{storageAvailable=false;}}
 function inspect(card:Card){selected=card;requestAnimationFrame(()=>document.getElementById('card-details')?.scrollIntoView({behavior:'smooth',block:'start'}));}
</script>
<svelte:head><title>Card gallery · Sabobatage</title><meta name="description" content="Explore a playful illustrated art direction for Sabobatage, the boba card game."/></svelte:head>
<main id="main">
 <section class="hero"><div class="hero-copy"><p class="eyebrow"><span>●</span> THE BOBA CARD GAME</p><h1>Sweet drinks.<br/><em>Sneaky moves.</em></h1><p class="hero-description">Build your boba empire. Stir up a little trouble.<br/>Meet the cards behind your next friendly betrayal.</p><a class="primary-button" href="#collection">Explore the cards <span>↘</span></a><div class="hero-meta"><span>2–5 players</span><span>Tea. Toppings. Treachery.</span></div></div><div class="hero-cards" aria-hidden="true"><div class="hero-card hero-card-left"><CardFace card={cards[0]}/></div><div class="hero-card hero-card-right"><CardFace card={cards[8]}/></div><div class="hero-card hero-card-center"><CardFace card={cards[4]}/></div><div class="hero-sticker">100% sweet<br/><b>0% innocent</b></div><span class="hero-sparkle">✳</span></div><div class="hero-bottom">FRESHLY BREWED CHARACTERS <span>✦</span> A LITTLE FRIENDLY SABOTAGE <span>✦</span> SERVED WITH EXTRA PERSONALITY</div></section>
 <section class="collection" id="collection"><div class="section-heading"><div><p class="eyebrow">THE FIRST POUR</p><h2>Meet your new <em>frenemies.</em></h2></div><p>{cards.length} card types · {deckSize} cards<br/><span>The complete base-game inventory.</span></p></div>
 <div class="collection-tools"><div class="filter-tabs" aria-label="Filter card categories">{#each categories as type}<button class:active={category===type} aria-pressed={category===type} onclick={()=>category=type}>{type}<span>{type==='All cards'?cards.length:cards.filter(c=>c.category===type).length}</span></button>{/each}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" aria-label="Search cards" placeholder="Find your flavor…" bind:value={query}/></label></div>
 <div class="collection-meta"><p aria-live="polite">Showing {visible.length} of {cards.length} types · {visible.reduce((total, card) => total + card.copies, 0)} copies <span>· Click a card for a closer look</span></p><div><label><input type="checkbox" bind:checked={large}/> Large cards</label><label><input type="checkbox" bind:checked={backs}/> Card backs</label></div></div>
{#if selected}<section id="card-details" class="inline-inspector" aria-label={`${selected.name} card details`}><button class="dialog-close" onclick={()=>selected=null} aria-label="Close card inspector">✕</button>{#if selected}<div class="inspector"><CardFace card={selected} back={backs}/><div class="inspector-copy"><p class="eyebrow">CARD STUDY {String(selected.art+1).padStart(2,'0')}</p><h2>{selected.name}</h2><p>{selected.effect}</p><p class="small">{selected.note}</p><dl><dt>Category</dt><dd>{selected.category}</dd><dt>Copies in current base deck</dt><dd>{selected.copies}</dd><dt>Rule reference</dt><dd>{selected.ruleSource==='official'?'Official card text':selected.ruleSource==='community'?'Community reference · unverified':selected.ruleSource==='user'?'User-confirmed card text':selected.verified?'Rulebook summary':'Full effect pending verification'}</dd></dl>{#if selected.sourceUrl}<p class="small"><a href={selected.sourceUrl} target="_blank" rel="noreferrer">{selected.ruleSource === 'community' ? 'Read community reference ↗' : 'Read official reference ↗'}</a></p>{/if}<button class="primary-button" onclick={()=>favorite(selected!.id)}>{favorites.includes(selected.id)?'♥ Saved to favorites':'♡ Save this artwork'}</button><button class="text-button" onclick={()=>backs=!backs}>{backs?'Show card front':'Show card back'}</button><p class="small">Close this detail panel to return to the gallery.</p></div></div>{/if}</section>{/if}

 <div class="card-grid" class:large>{#each visible as card}<div class="card-item"><button class="inspect-card" onclick={()=>inspect(card)} aria-label={`Inspect ${card.name}`}><CardFace {card} back={backs}/></button><div class="card-caption"><span><i class={`category-dot ${card.category.toLowerCase()}`}></i>{card.category} <span class="caption-divider">/</span> {card.family}<strong class="copy-count">×{card.copies}</strong></span><button class:hearted={favorites.includes(card.id)} aria-label={`${favorites.includes(card.id)?'Unsave':'Save'} ${card.name} art`} aria-pressed={favorites.includes(card.id)} onclick={()=>favorite(card.id)}>{favorites.includes(card.id)?'♥':'♡'}</button></div></div>{:else}<div class="empty"><h3>No pearls found.</h3><p>Try another ingredient or card name.</p><button class="primary-button" onclick={()=>{query='';category='All cards';}}>Reset filters</button></div>{/each}</div>
 <div class="review-note"><span class="note-icon">✳</span><div><h3>A little cute. A little chaotic.</h3><p>Warm paper, bold ink, and expressive boba-shop characters. Tap ♡ to save favorites {storageAvailable?'in this browser':'for this session'}. All {cards.length} base-game card types are here. {pendingEffects ? `${pendingEffects} action effects still need printed-text verification.` : 'Every card effect is documented.'}</p></div><a href="#direction">The design recipe ↗</a></div>
 </section>
 <section class="direction" id="direction"><div><p class="eyebrow">ART DIRECTION 01 · BOBA MISCHIEF</p><h2>Small shop.<br/><em>Big personality.</em></h2></div><div><p>Friendly ingredients. Mischievous actions. A tactile, illustrated world inspired by neighborhood tea shops, with a consistent card frame that keeps the rules easy to read.</p><div class="palette"><span style="--swatch:#eec4cd">Strawberry</span><span style="--swatch:#c5d398">Matcha</span><span style="--swatch:#c9b4dc">Taro</span><span style="--swatch:#583c32">Brown sugar</span></div><p class="small">Original generated artwork · Live, selectable card text · Pantheon-inspired gallery structure</p></div></section>
</main>
